import{_ as d,I as t,o,c as p,j as e,a as l,J as i,w as h,a5 as s}from"./chunks/framework.D4tbZp_W.js";const x=JSON.parse('{"title":"把零散知识沉淀为可复用体系","description":"从捕获、压缩、连接到输出，建立一套可长期维护的个人知识系统。","frontmatter":{"title":"把零散知识沉淀为可复用体系","description":"从捕获、压缩、连接到输出，建立一套可长期维护的个人知识系统。"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786328197000}'),b={name:"index.md"};function m(c,a,u,_,k,g){const r=t("SummaryHero"),n=t("StatGrid");return o(),p("div",null,[a[1]||(a[1]=e("h1",{id:"初级一-把零散知识沉淀为可复用体系",tabindex:"-1"},[l("初级一：把零散知识沉淀为可复用体系 "),e("a",{class:"header-anchor",href:"#初级一-把零散知识沉淀为可复用体系","aria-label":"Permalink to “初级一：把零散知识沉淀为可复用体系”"},"​")],-1)),a[2]||(a[2]=e("p",null,"这是一个可以直接拿来维护的知识总结框架。你可以跟随下面的路径，把读过的文章、解决过的问题和完成过的项目，逐步沉淀成真正能被检索、复用和分享的知识。",-1)),a[3]||(a[3]=e("p",null,"不要担心一开始的结构不够完美，请先记住：",-1)),a[4]||(a[4]=e("blockquote",null,[e("p",null,"完成一次清晰的输出，比收藏一百条链接更重要 🐣")],-1)),a[5]||(a[5]=e("h2",{id:"本章导读",tabindex:"-1"},[l("本章导读 "),e("a",{class:"header-anchor",href:"#本章导读","aria-label":"Permalink to “本章导读”"},"​")],-1)),i(r,{goals:["知识捕获","渐进式总结","主题连接"],duration:"约 40 分钟，可分段完成",output:"1 张知识地图 + 1 篇结构化总结"},{default:h(()=>[...a[0]||(a[0]=[e("p",null,"如果你经常收藏很多内容，却很难在真正需要时找到或讲清楚它们，这一章就是为你准备的。我们不会从复杂工具开始，而是先建立一个足够简单、可以持续执行的闭环。",-1)])]),_:1}),a[6]||(a[6]=s('<h2 id="_1-收藏不是知识-能被调用的才是" tabindex="-1">1. 收藏不是知识，能被调用的才是 <a class="header-anchor" href="#_1-收藏不是知识-能被调用的才是" aria-label="Permalink to “1. 收藏不是知识，能被调用的才是”">​</a></h2><p>我们每天都在接触新信息：文章、视频、会议记录、代码片段和临时灵感。问题通常不是信息太少，而是信息进入系统后没有经历筛选、压缩和连接，最后只剩下一个越来越大的“稍后阅读”列表。</p><p>一个可工作的知识系统，至少需要完成四件事：</p><ol><li><strong>捕获</strong>：只记录对当前问题真正有价值的材料。</li><li><strong>压缩</strong>：把原始内容转换成自己的语言。</li><li><strong>连接</strong>：说明它与已有知识、项目或决策的关系。</li><li><strong>输出</strong>：让知识在写作、沟通或实践中被使用。</li></ol>',4)),i(n,{title:"从信息到行动的四个关键动作",items:[{value:"1 分钟",label:"快速捕获"},{value:"3 层",label:"渐进压缩"},{value:"2 条",label:"关联线索"},{value:"1 次",label:"真实输出"}]}),a[7]||(a[7]=s(`<p>当每条笔记都能回答“它解决什么问题”和“下一次何时会用到”，你的知识库才开始从仓库变成工作台。</p><h2 id="_2-一套足够简单的知识闭环" tabindex="-1">2. 一套足够简单的知识闭环 <a class="header-anchor" href="#_2-一套足够简单的知识闭环" aria-label="Permalink to “2. 一套足够简单的知识闭环”">​</a></h2><h3 id="_2-1-捕获-先写下为什么值得留下" tabindex="-1">2.1 捕获：先写下为什么值得留下 <a class="header-anchor" href="#_2-1-捕获-先写下为什么值得留下" aria-label="Permalink to “2.1 捕获：先写下为什么值得留下”">​</a></h3><p>不要只保存标题和链接。每次捕获时增加一句自己的判断：</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">来源：文章 / 会议 / 项目</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">核心问题：它在回答什么？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">留下原因：我准备在哪里使用？</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这三行会迫使你在信息进入知识库之前完成第一次筛选，也能显著降低日后重新理解上下文的成本。</p><div class="tip custom-block"><p class="custom-block-title">💡 什么是高质量捕获？</p><p>高质量捕获不是把原文复制得更完整，而是保留足够的上下文，让未来的你在 30 秒内判断它是否值得继续阅读。</p></div><h3 id="_2-2-压缩-从摘录走向自己的表达" tabindex="-1">2.2 压缩：从摘录走向自己的表达 <a class="header-anchor" href="#_2-2-压缩-从摘录走向自己的表达" aria-label="Permalink to “2.2 压缩：从摘录走向自己的表达”">​</a></h3><p>同一条材料可以分三轮处理：第一轮标出关键句，第二轮写出三条核心结论，第三轮只保留一个能指导行动的判断。你不必一次完成全部压缩，真正需要使用时再继续加工即可。</p><table tabindex="0"><thead><tr><th>层级</th><th>产物</th><th>适用时机</th></tr></thead><tbody><tr><td>原始材料</td><td>链接、截图、摘录</td><td>刚接触内容时</td></tr><tr><td>核心结论</td><td>3—5 条自己的表述</td><td>判断值得保留后</td></tr><tr><td>行动摘要</td><td>一句话结论与使用条件</td><td>准备写作或决策时</td></tr></tbody></table><h3 id="_2-3-连接-让单篇笔记进入知识网络" tabindex="-1">2.3 连接：让单篇笔记进入知识网络 <a class="header-anchor" href="#_2-3-连接-让单篇笔记进入知识网络" aria-label="Permalink to “2.3 连接：让单篇笔记进入知识网络”">​</a></h3><p>一篇孤立的好笔记仍然很难被发现。整理结束前，至少补充两种连接：</p><ul><li><strong>向上连接主题</strong>：它属于哪个长期关注的问题？</li><li><strong>向前连接行动</strong>：它能推进哪个项目、文章或决策？</li></ul><p>如果暂时找不到连接，不必强行分类。将它放入“待验证”区域，等真实场景出现后再决定归属。</p><h2 id="_3-动手-完成第一篇结构化总结" tabindex="-1">3. 动手：完成第一篇结构化总结 <a class="header-anchor" href="#_3-动手-完成第一篇结构化总结" aria-label="Permalink to “3. 动手：完成第一篇结构化总结”">​</a></h2><h3 id="_3-1-选择一个真实问题" tabindex="-1">3.1 选择一个真实问题 <a class="header-anchor" href="#_3-1-选择一个真实问题" aria-label="Permalink to “3.1 选择一个真实问题”">​</a></h3><p>从你本周正在处理的事情里，挑一个边界清晰的问题。例如“怎样减少前端首屏加载时间”，而不是宽泛的“学习前端性能”。问题越具体，材料筛选和总结就越容易。</p><h3 id="_3-2-用五段式模板完成输出" tabindex="-1">3.2 用五段式模板完成输出 <a class="header-anchor" href="#_3-2-用五段式模板完成输出" aria-label="Permalink to “3.2 用五段式模板完成输出”">​</a></h3><blockquote><p>💡 示例模板</p><ol><li>我在解决什么问题？</li><li>当前已知事实是什么？</li><li>最重要的三条洞察是什么？</li><li>有哪些限制或反例？</li><li>下一步要采取什么行动？</li></ol></blockquote><p>写完后，尝试把总结讲给一个不了解背景的人。如果对方能复述你的核心判断，并知道下一步做什么，这篇总结就已经完成了它的任务。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 避免“看起来很努力”的整理</p><p>大量标签、复杂目录和精美封面不会自动提升知识价值。优先保证问题、结论、证据和行动清晰，再逐步优化形式。</p></div><h2 id="_4-让系统持续运转" tabindex="-1">4. 让系统持续运转 <a class="header-anchor" href="#_4-让系统持续运转" aria-label="Permalink to “4. 让系统持续运转”">​</a></h2><p>你不需要每天整理整个知识库。更可持续的节奏是：随手捕获、每周压缩、按项目输出、每月清理。知识系统应该服务真实工作，而不是成为另一份需要维护的工作。</p><p>下一步可以打开 <a href="/knowledge-summary/guide/knowledge-map">知识地图</a>，建立你的第一层主题结构；也可以直接查看 <a href="/knowledge-summary/appendix/maintenance">内容维护指南</a>，了解怎样新增页面并部署更新。</p>`,24))])}const P=d(b,[["render",m]]);export{x as __pageData,P as default};
